package fr.crewcmoi.teleport.gui;
import fr.crewcmoi.Main; import fr.crewcmoi.other.utils.GuiItems; import fr.crewcmoi.teleport.database.HomeData; import fr.crewcmoi.teleport.managers.HomeManager; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.*; import java.util.*;
public class HomeAdminGuiManager { private final Main plugin; private final HomeManager manager; public HomeAdminGuiManager(Main p,HomeManager m){plugin=p;manager=m;} public void open(Player p){open(p,0);} public void open(Player p,int page){Bukkit.getScheduler().runTaskAsynchronously(plugin,()->{List<HomeData> homes=manager.getAllHomes();Bukkit.getScheduler().runTask(plugin,()->{HomeAdminHolder h=new HomeAdminHolder();int max=Math.max(0,(homes.size()-1)/45);h.setPage(Math.max(0,Math.min(page,max)));Inventory inv=Bukkit.createInventory(h,54,color("&8&lʜᴏᴍᴇꜱ • ᴀᴅᴍɪɴ &7• &f"+(h.getPage()+1)));h.setInventory(inv);render(h,homes);p.openInventory(inv);});});} private void render(HomeAdminHolder h,List<HomeData> homes){Inventory inv=h.getInventory();h.clear();for(int i=0;i<54;i++)inv.setItem(i,GuiItems.nothing(" "));int start=h.getPage()*45,end=Math.min(start+45,homes.size());for(int i=start;i<end;i++){HomeData home=homes.get(i);int slot=i-start;inv.setItem(slot,item(home));h.map(slot,home);}if(h.getPage()>0)inv.setItem(45,button(Material.ARROW,"&e« ᴘʀᴇᴄᴇᴅᴇɴᴛ"));if(end<homes.size())inv.setItem(53,button(Material.ARROW,"&eꜱᴜɪᴠᴀɴᴛ »"));}private ItemStack item(HomeData h){ItemStack it=new ItemStack(Material.PLAYER_HEAD);SkullMeta m=(SkullMeta)it.getItemMeta();m.setOwningPlayer(Bukkit.getOfflinePlayer(h.getUuid()));m.setDisplayName(color("&e&l"+h.getName()+" &7• &f"+(h.getOwnerName()==null?"Inconnu":h.getOwnerName())));m.setLore(Arrays.asList(color("&7ᴍᴏɴᴅᴇ : &f"+h.getWorld()),color("&7ᴄᴏᴏʀᴅᴏɴɴᴇᴇꜱ : &f"+fmt(h.getX())+" &7/ &f"+fmt(h.getY())+" &7/ &f"+fmt(h.getZ())),"",color("&aᴄʟɪǫᴜᴇᴢ ᴘᴏᴜʀ ᴛᴇʟᴇᴘᴏʀᴛᴇʀ")));it.setItemMeta(m);return it;}private ItemStack button(Material mat,String n){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(color(n));i.setItemMeta(m);return i;}private String fmt(double d){return String.format(Locale.US,"%.1f",d);}private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);}public void teleport(Player p,HomeData h){World w=Bukkit.getWorld(h.getWorld());if(w!=null)p.teleport(new Location(w,h.getX(),h.getY(),h.getZ(),h.getYaw(),h.getPitch()));}}
